#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Density {
    Comfortable,
    Compact,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Metrics {
    pub control_height: f32,
    pub row_height: f32,
    pub control_padding_x: f32,
    pub control_padding_y: f32,
}

pub const fn dimensions(density: Density, touch: bool) -> Metrics {
    match (density, touch) {
        (Density::Compact, false) => Metrics {
            control_height: 32.0,
            row_height: 36.0,
            control_padding_x: 12.0,
            control_padding_y: 5.0,
        },
        _ => Metrics {
            control_height: 44.0,
            row_height: 48.0,
            control_padding_x: 16.0,
            control_padding_y: 10.0,
        },
    }
}

